('neco','e3b0d03f-acf7-4ddb-9755-7f4072459e76'::uuid,'Constitution & Legislature','How many senators make up Nigeria''s Senate?','[{"id":"A","text":"109"},{"id":"B","text":"360"},{"id":"C","text":"36"},{"id":"D","text":"74"}]'::jsonb,'A','The Senate has 109 senators.','medium','National Assembly of Nigeria','https://nass.gov.ng/about/item/1548','authoritative-web',now(),true,now()),
('neco','e3b0d03f-acf7-4ddb-9755-7f4072459e76'::uuid,'Constitution & Legislature','Nigeria''s National Assembly is:','[{"id":"A","text":"Non-legislative"},{"id":"B","text":"Bicameral"},{"id":"C","text":"Unicameral"},{"id":"D","text":"Tricameral"}]'::jsonb,'B','The National Assembly has two chambers: the Senate and the House of Representatives.','medium','National Assembly of Nigeria','https://nass.gov.ng/about/item/1548','authoritative-web',now(),true,now()),
('neco','e3b0d03f-acf7-4ddb-9755-7f4072459e76'::uuid,'Constitution & Legislature','The Federal Capital Territory contributes how many senatorial district to the Senate?','[{"id":"A","text":"None"},{"id":"B","text":"One"},{"id":"C","text":"Two"},{"id":"D","text":"Three"}]'::jsonb,'B','The FCT is represented by one senatorial district.','medium','National Assembly of Nigeria','https://nass.gov.ng/about/item/1548','authoritative-web',now(),true,now()),
